ruleToc.chapterUrl:
a@href<js>
if(result.match(/novel/)){
		result=result;
		}else if(result.match(/goChapter/)){
	var aid=java.get("aid");
	var key=source.getKey();
	var go=result.match(/goChapter\((\d+)\)/);
	if(go&&go[1]){
		go=go[1];
	var url=`${key}/novel/${aid}/${go}.html`;
	}else{go="";url=""}
	result=String(url);
	}else {
			java.toast("如未获取到链接，可在右上角三点刷新后再试。还不行就是末尾章节链接为空，没有更新。");
			}
</js>##$##,{'webView': true}

